// --- Contract's model tier -------------------------------------------
//
// Random sequences of Contract's methods, run against every subject and
// something that judges them from outside. The rows on the run surface
// above carry it, and ContractSuite.Without declines any of them by name.
//
//	Reference: derived — the VersionedCell oracle, which is the
//	           cas contract's own semantics; NewContractModelReference replaces it
//	Sequences: Put (cas.writer), Get (aggregator)
//	Not bound:
//	           AUTO-WRITE-OBSERVABLE — Read names the reader family, and the interface has no keyed reader

// contractModelKeys is the key pool every key slot draws from.
//
// Two keys, and deliberately not more: collision density is what makes a
// read revisit a write and an overwrite land on held state. A wide key
// pool would pass every comparison over a history that never collides.
func contractModelKeys(fx ContractFixture) *model.Generator[cas.Value] {
	return model.SampledFrom([]cas.Value{fx.Value(), fx.ValueOther()})
}

// contractModelVersionOf projects a value's version — the one
// derivation the cell guards writes by, shared so the oracle and any law
// cannot disagree about which field is the guard.
func contractModelVersionOf(v cas.Value) int64 {
	return v.Version
}

// contractModelEmpty is the oracle's spelling; only its presence is compared, so a
// subject reporting its own error under the same state agrees with it.
var contractModelEmpty = errors.New("contract: the cell holds nothing yet")

// contractModelReference adapts the shipped VersionedCell oracle — the
// cas contract's own semantics — to Contract.
// Deliberately simple: its correctness is read, not tested.
type contractModelReference struct {
	store *ref.VersionedCell[cas.Value]
}

// NewContractModelReference builds one. Exported because a consumer whose
// semantics outrun their shape replaces it, and because the proof beside
// this file drives it as a subject of its own.
func NewContractModelReference() Contract {
	return &contractModelReference{store: ref.NewVersionedCell[cas.Value](
		contractModelVersionOf,
		cas.ErrMismatch,
		contractModelEmpty,
	)}
}

func (r *contractModelReference) Put(ctx context.Context, v cas.Value) error {
	return r.store.Put(ctx, v)
}

func (r *contractModelReference) Get(ctx context.Context) (cas.Value, error) {
	return r.store.Get(ctx)
}

// contractModelActions is the operation vocabulary both legs drive.
//
// One constructor per method shape, from the engine's action set rather
// than hand-written closures: the constructors record inputs and outputs
// into the trace a law reads, compare the two sides the same way for every
// action, and shrink a failing sequence to the shortest one that still
// fails.
func contractModelActions(fx ContractFixture) []model.Action[Contract] {
	keys := contractModelKeys(fx)
	return []model.Action[Contract]{
		action.CompareAndSwap("Put", keys,
			func(ctx context.Context, s cas.Contract, v cas.Value) error {
				return s.Put(ctx, v)
			}),
		action.Aggregator("Get",
			func(ctx context.Context, s cas.Contract) (cas.Value, error) {
				return s.Get(ctx)
			}),
	}
}

// contractAssertAgrees drives random operation sequences against the subject and
// the reference, comparing after every call.
//
// The differential is the strongest oracle this tier has, and it is this
// leg's whole job: no laws are registered, so nothing competes with it and
// a disagreement is what ends the run.
func contractAssertAgrees(
	tb testing.TB,
	sub suite.Subject[Contract],
	fx ContractFixture,
) {
	tb.Helper()
	legs.Differential(tb, sub,
		NewContractModelReference,
		contractModelActions(fx))
}

// contractAssertLinearizable drives concurrent workers against one instance and asks
// whether the history they recorded has a serial explanation.
//
// A claim no sequential leg can state. The differential compares one
// ordered run against a reference and the laws hold after each step of
// one; this is about what a caller may observe when there is no single
// order at all, and the model is what decides whether one exists.
//
// The engine owns the interleaving, the property loop and the artifact a
// failing history is written to. This supplies the verbs and the model.
func contractAssertLinearizable(
	tb testing.TB,
	sub suite.Subject[Contract],
	fx ContractFixture,
) {
	tb.Helper()
	keys := contractModelKeys(fx)
	legs.Concurrent(tb, sub,
		NewContractModelReference,
		model.ConcurrentConfig[Contract]{
			Model: linearize.CASCell[cas.Value, int64](
				nil, cas.ErrMismatch,
				func(v cas.Value) int64 { return v.Version },
				func(seen int64) int64 { return seen + 1 },
			),
			Actions: []model.ConcurrentAction[Contract]{
				linearize.ConcurrentCellReader(linearize.OpGet,
					func(ctx context.Context, s cas.Contract) (cas.Value, error) {
						return s.Get(ctx)
					}),
				linearize.ConcurrentCAS(linearize.OpCAS, keys,
					func(ctx context.Context, s cas.Contract, v cas.Value) error {
						return s.Put(ctx, v)
					}),
			},
		})
}

// contractAssertCASAtomicOneWinner binds AUTO-CAS-ATOMIC-ONE-WINNER over the shared sequences.
//
// One law, and the run's only oracle. The differential is off here, as
// on every law leg: with it armed a subject broken anywhere disagrees at
// step 0, and whether THIS law can catch a defect stays unanswerable.
func contractAssertCASAtomicOneWinner(
	tb testing.TB,
	sub suite.Subject[Contract],
	fx ContractFixture,
) {
	tb.Helper()
	// The inputs pool is the law's own: a wide domain for a stateless
	// claim, which the colliding pair deliberately does not serve.
	inputs := model.Make[cas.Value]()

	buildRef, tier := legs.Reference(tb, sub, NewContractModelReference)
	sub.NoteTier(tier)
	legs.Law(tb, sub,
		func() Contract { return sub.New(tb) }, buildRef,
		contractModelActions(fx),
		[]law.Law[Contract]{
			law.CASAtomicOneWinner[cas.Contract, cas.Value]{
				CAS: func(rt *model.T, s cas.Contract, v cas.Value) error {
					return s.Put(rt.Context(), v)
				},
				Read: func(rt *model.T, s cas.Contract) (cas.Value, error) {
					return s.Get(rt.Context())
				},
				Values: inputs,
				Stamp: func(rt *model.T, s cas.Contract, v cas.Value) cas.Value {
					cur, err := s.Get(rt.Context())
					if err != nil {
						v.Version = 0
						return v
					}
					v.Version = cur.Version + 1
					return v
				},
				Mismatch: cas.ErrMismatch,
			},
		})
}

// contractAssertCounts binds AUTO-COUNT-EQUALS-REFERENCE over the shared sequences.
//
// One law, and the run's only oracle. The differential is off here, as
// on every law leg: with it armed a subject broken anywhere disagrees at
// step 0, and whether THIS law can catch a defect stays unanswerable.
func contractAssertCounts(
	tb testing.TB,
	sub suite.Subject[Contract],
	fx ContractFixture,
) {
	tb.Helper()

	buildRef, tier := legs.Reference(tb, sub, NewContractModelReference)
	sub.NoteTier(tier)
	legs.Law(tb, sub,
		func() Contract { return sub.New(tb) }, buildRef,
		contractModelActions(fx),
		[]law.Law[Contract]{
			law.CountEqualsReference[cas.Contract, cas.Value]{
				Count: func(rt *model.T, s cas.Contract) (cas.Value, error) {
					return s.Get(rt.Context())
				},
			},
		})
}

